function largestPalindromic(num) {
  const count = new Array(10).fill(0);
  for (const ch of num) {
    count[Number(ch)]++;
  }
  let half = '';
  for (let digit = 9; digit >= 0; digit--) {
    if (digit === 0 && half === '') {
      break;
    }
    const pairs = Math.floor(count[digit] / 2);
    half += String(digit).repeat(pairs);
    count[digit] -= 2 * pairs;
  }
  let middle = '';
  for (let digit = 9; digit >= 0; digit--) {
    if (count[digit] > 0) {
      middle = String(digit);
      break;
    }
  }
  const mirrored = half.split('').reverse().join('');
  return half + middle + mirrored;
}

