function largestPalindromic(num) {
  // Try every distinct arrangement of every sub-multiset of the digits and keep the largest valid palindrome.
  const left = new Array(10).fill(0);
  for (const ch of num) left[ch.charCodeAt(0) - 48]++;
  let answer = null;
  const better = (a, b) => b === null || a.length > b.length || (a.length === b.length && a > b);
  const visit = (built) => {
    if (built.length > 0 && (built.length === 1 || built[0] !== '0')) {
      if (built === built.split('').reverse().join('') && better(built, answer)) answer = built;
    }
    for (let d = 0; d < 10; d++) {
      if (left[d] === 0) continue;
      left[d]--;
      visit(built + d);
      left[d]++;
    }
  };
  visit('');
  return answer;
}

